import textwrap
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import Any, Dict, List, Optional, Tuple

import viktor as vkt

try:
    import ifcopenshell
    import ifcopenshell.util.element
    import ifcopenshell.util.shape
except Exception:  # pragma: no cover
    ifcopenshell = None


# ------------------------------
# Helpers
# ------------------------------

def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except Exception:
        return None


def _first_value(*values: Any) -> Any:
    for v in values:
        if v is None:
            continue
        if isinstance(v, str) and not v.strip():
            continue
        return v
    return None


def _get_psets_dict(ifc_element) -> Dict[str, Dict[str, Any]]:
    """Returns psets/qto dict.

    ifcopenshell.util.element.get_psets returns a nested dict with pset names as keys.
    """
    try:
        return ifcopenshell.util.element.get_psets(ifc_element) or {}
    except Exception:
        return {}


def _find_property(psets: Dict[str, Dict[str, Any]], pset_candidates: List[str], prop_candidates: List[str]) -> Any:
    for pset_name in pset_candidates:
        pset = psets.get(pset_name)
        if not isinstance(pset, dict):
            continue
        for prop_name in prop_candidates:
            if prop_name in pset:
                v = pset.get(prop_name)
                if v is not None and (not isinstance(v, str) or v.strip()):
                    return v
    return None


def _get_storey_name(model, element) -> str:
    try:
        storey = ifcopenshell.util.element.get_container(element)
        if storey is None:
            return ""
        return (getattr(storey, "Name", None) or "").strip()
    except Exception:
        return ""


def _get_space_number(space, psets: Dict[str, Dict[str, Any]]) -> str:
    # Common conventions: Pset_SpaceCommon.Reference, or custom properties like RoomNumber / Number
    val = _find_property(
        psets,
        pset_candidates=["Pset_SpaceCommon", "Pset_SpaceCommon"],
        prop_candidates=["Reference", "Number", "RoomNumber", "Id", "Identifier"],
    )

    # Fallback to LongName (often used as room number in some authoring tools)
    val = _first_value(val, getattr(space, "LongName", None))
    return (str(val).strip() if val is not None else "")


def _get_space_name(space, psets: Dict[str, Dict[str, Any]]) -> str:
    # IFC attribute fallback chain
    val = _first_value(getattr(space, "Name", None), getattr(space, "LongName", None))

    # If still empty, try a few non-standard properties that occur in practice
    if not val:
        val = _find_property(
            psets,
            pset_candidates=["Pset_SpaceCommon", "Pset_SpaceCustom", "Identity Data"],
            prop_candidates=["Name", "RoomName", "SpaceName"],
        )
    return (str(val).strip() if val is not None else "")


def _get_area_and_volume_from_quantities(psets: Dict[str, Dict[str, Any]]) -> Tuple[Optional[float], Optional[float], str, str]:
    """Return (area, volume, area_source, volume_source)."""

    # Preferred: Qto_SpaceBaseQuantities
    qto = psets.get("Qto_SpaceBaseQuantities", {}) if isinstance(psets.get("Qto_SpaceBaseQuantities"), dict) else {}

    area = _to_float(_first_value(qto.get("NetFloorArea"), qto.get("GrossFloorArea")))
    area_source = "Qto_SpaceBaseQuantities" if area is not None else ""

    volume = _to_float(_first_value(qto.get("NetVolume"), qto.get("GrossVolume")))
    volume_source = "Qto_SpaceBaseQuantities" if volume is not None else ""

    # Fallback: planned areas in Pset_SpaceCommon (not always present, but helps)
    if area is None:
        psc = psets.get("Pset_SpaceCommon", {}) if isinstance(psets.get("Pset_SpaceCommon"), dict) else {}
        area = _to_float(_first_value(psc.get("NetPlannedArea"), psc.get("GrossPlannedArea")))
        if area is not None:
            area_source = "Pset_SpaceCommon"

    return area, volume, area_source, volume_source


def _try_geometry_area_volume(space) -> Tuple[Optional[float], Optional[float]]:
    """Attempt to compute missing quantities from geometry.

    This can fail for many reasons (no geometry, missing OpenCascade, invalid representation).
    """
    try:
        area = _to_float(ifcopenshell.util.shape.get_footprint_area(space))
    except Exception:
        area = None

    try:
        volume = _to_float(ifcopenshell.util.shape.get_volume(space))
    except Exception:
        volume = None

    return area, volume


def _open_ifc_from_viktor_file(vkt_file: vkt.File):
    """IfcOpenShell expects a file path; we write the uploaded IFC to a temp file."""

    raw = vkt_file.getvalue()
    if isinstance(raw, str):
        raw = raw.encode("utf-8", errors="ignore")

    with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
        tmp.write(raw)
        tmp_path = Path(tmp.name)

    return ifcopenshell.open(str(tmp_path))


# ------------------------------
# Viktor app
# ------------------------------


class Parametrization(vkt.Parametrization):
    inputs = vkt.Section("IFC input")
    inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Room schedule (IfcSpace)

            Upload an IFC file to generate a **room schedule** from all `IfcSpace` elements.

            The app extracts:
            - **Storey** (if available)
            - **Room number** (typically `Pset_SpaceCommon.Reference`)
            - **Room name** (`IfcSpace.Name`)
            - **Area** (typically `Qto_SpaceBaseQuantities.NetFloorArea`)
            - **Volume** (typically `Qto_SpaceBaseQuantities.NetVolume`)

            Spaces with missing key data are **flagged**.
            """
        )
    )

    inputs.ifc_file = vkt.FileField("IFC file", file_types=[".ifc"])  # required upload
    inputs.only_flagged = vkt.BooleanField("Show only flagged spaces", default=False)
    inputs.try_geometry = vkt.BooleanField(
        "Try to compute missing area/volume from geometry (slower)",
        default=False,
        description="Uses IfcOpenShell geometry utilities; may fail depending on IFC content and environment.",
    )


class Controller(vkt.Controller):
    parametrization = Parametrization

    label = "Room schedule (IfcSpace)"

    def _get_spaces_table_rows(self, params) -> Tuple[List[List[Any]], Dict[str, int]]:
        """Build table rows + basic statistics."""

        stats = {
            "spaces": 0,
            "flagged": 0,
            "missing_name": 0,
            "missing_number": 0,
            "missing_area": 0,
            "missing_volume": 0,
            "area_from_geometry": 0,
            "volume_from_geometry": 0,
        }

        if ifcopenshell is None:
            raise vkt.UserError(
                "IfcOpenShell is not available in this environment. Add 'ifcopenshell' to requirements.txt."
            )

        if not getattr(params.inputs, "ifc_file", None) or not getattr(params.inputs.ifc_file, "file", None):
            return [], stats

        model = _open_ifc_from_viktor_file(params.inputs.ifc_file.file)
        spaces = model.by_type("IfcSpace") or []

        rows: List[List[Any]] = []

        for space in spaces:
            stats["spaces"] += 1

            psets = _get_psets_dict(space)

            storey_name = _get_storey_name(model, space)
            number = _get_space_number(space, psets)
            name = _get_space_name(space, psets)

            area, volume, area_src, vol_src = _get_area_and_volume_from_quantities(psets)

            # Optional geometry fallback
            if params.inputs.try_geometry:
                if area is None or volume is None:
                    g_area, g_vol = _try_geometry_area_volume(space)
                    if area is None and g_area is not None:
                        area = g_area
                        area_src = "Geometry"
                        stats["area_from_geometry"] += 1
                    if volume is None and g_vol is not None:
                        volume = g_vol
                        vol_src = "Geometry"
                        stats["volume_from_geometry"] += 1

            missing: List[str] = []
            if not name:
                missing.append("NO_NAME")
                stats["missing_name"] += 1
            if not number:
                missing.append("NO_NUMBER")
                stats["missing_number"] += 1
            if area is None:
                missing.append("NO_AREA")
                stats["missing_area"] += 1
            if volume is None:
                missing.append("NO_VOLUME")
                stats["missing_volume"] += 1

            is_flagged = len(missing) > 0
            if is_flagged:
                stats["flagged"] += 1

            if params.inputs.only_flagged and not is_flagged:
                continue

            # Styling: highlight missing values
            ok_bg = None
            warn_bg = vkt.Color(255, 235, 235)  # light red
            geom_bg = vkt.Color(255, 249, 196)  # light yellow

            def cell(value, is_missing=False, is_geom=False):
                if is_missing:
                    return vkt.TableCell(value if value is not None else "", background_color=warn_bg)
                if is_geom:
                    return vkt.TableCell(value if value is not None else "", background_color=geom_bg)
                return value if value is not None else ""

            rows.append(
                [
                    storey_name,
                    cell(number, is_missing=("NO_NUMBER" in missing)),
                    cell(name, is_missing=("NO_NAME" in missing)),
                    cell(area, is_missing=("NO_AREA" in missing), is_geom=(area_src == "Geometry")),
                    cell(volume, is_missing=("NO_VOLUME" in missing), is_geom=(vol_src == "Geometry")),
                    vkt.TableCell(
                        ", ".join(missing),
                        background_color=warn_bg if is_flagged else ok_bg,
                        text_style="bold" if is_flagged else None,
                    ),
                ]
            )

        # Stable ordering: storey, number, name
        def _sort_key(r):
            return (
                str(r[0] or "").lower(),
                str(r[1].value if isinstance(r[1], vkt.TableCell) else r[1] or "").lower(),
                str(r[2].value if isinstance(r[2], vkt.TableCell) else r[2] or "").lower(),
            )

        rows.sort(key=_sort_key)
        return rows, stats

    @vkt.DataView("Summary")
    def summary_view(self, params, **kwargs):
        try:
            _, stats = self._get_spaces_table_rows(params)
        except vkt.UserError as e:
            return vkt.DataResult(vkt.DataGroup(vkt.DataItem("Error", str(e), status=vkt.DataStatus.ERROR)))

        if stats["spaces"] == 0:
            info = vkt.DataGroup(
                vkt.DataItem("IfcSpace found", 0, status=vkt.DataStatus.WARNING, status_message="Upload an IFC file to begin."),
            )
            return vkt.DataResult(info)

        data = vkt.DataGroup(
            vkt.DataItem("IfcSpace found", stats["spaces"], status=vkt.DataStatus.INFO),
            vkt.DataItem(
                "Flagged (missing data)",
                stats["flagged"],
                status=vkt.DataStatus.WARNING if stats["flagged"] else vkt.DataStatus.SUCCESS,
            ),
            vkt.DataItem("Missing name", stats["missing_name"], status=vkt.DataStatus.INFO),
            vkt.DataItem("Missing number", stats["missing_number"], status=vkt.DataStatus.INFO),
            vkt.DataItem("Missing area", stats["missing_area"], status=vkt.DataStatus.INFO),
            vkt.DataItem("Missing volume", stats["missing_volume"], status=vkt.DataStatus.INFO),
            vkt.DataItem("Area computed from geometry", stats["area_from_geometry"], status=vkt.DataStatus.INFO),
            vkt.DataItem("Volume computed from geometry", stats["volume_from_geometry"], status=vkt.DataStatus.INFO),
        )
        return vkt.DataResult(data)

    @vkt.TableView("Room schedule")
    def room_schedule_view(self, params, **kwargs):
        try:
            rows, _ = self._get_spaces_table_rows(params)
        except vkt.UserError as e:
            return vkt.TableResult([[str(e)]], column_headers=["Error"])

        headers = [
            "Storey",
            "Number",
            "Name",
            vkt.TableHeader("Area", num_decimals=2),
            vkt.TableHeader("Volume", num_decimals=2),
            "Missing data",
        ]

        return vkt.TableResult(rows, column_headers=headers)

    @vkt.IFCView("IFC model")
    def ifc_view(self, params, **kwargs):
        if not getattr(params.inputs, "ifc_file", None) or not getattr(params.inputs.ifc_file, "file", None):
            # Empty placeholder: IFCResult expects a file; show a message instead via TableView/DataView.
            raise vkt.UserError("Upload an IFC file to view the model.")
        return vkt.IFCResult(params.inputs.ifc_file.file)
